PREFIX a: <http://aegis.gastown.local/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?record ?g ?e ?t ?repo ?sha ?actor ?artifact WHERE {
{ SELECT ("event" AS ?record) ?g ?e ?t ?repo ?sha ?actor ?artifact WHERE { VALUES ?g { <{monthNow}> <{monthPrev}> } GRAPH ?g { ?e a a:ReleaseEvent ; a:occurredAt ?t ; a:changeRepository ?repo ; a:commitSha ?sha ; a:eventActor ?actor ; a:artifactId ?artifact . FILTER(xsd:dateTime(?t)>=xsd:dateTime('{since}') && xsd:dateTime(?t)<xsd:dateTime('{until}')) } } ORDER BY DESC(?t) ?e LIMIT 101 }
UNION { VALUES ?g { <{monthNow}> <{monthPrev}> } GRAPH ?g {} BIND("coverage" AS ?record) }
} LIMIT 104
